import { execFile } from 'node:child_process';
import { readFile } from 'node:fs/promises';
import { extname, relative, resolve } from 'node:path';
import { promisify } from 'node:util';

// Emoji and other pictographic characters are not allowed in code, comments, logs, error
// messages, UI text or documentation. Post content generated by the AI is data, not repository
// content, and never lives in these files.
//
// Only files that Git tracks are scanned. Generated and ignored output (node_modules, dist,
// the Prisma client) is therefore never part of the check.
const PICTOGRAPHIC = /\p{Extended_Pictographic}/u;
const SCANNED_EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.mjs', '.cjs', '.json', '.md', '.yml', '.yaml']);

const execFileAsync = promisify(execFile);

function isScanned(path: string): boolean {
  const name = path.split('/').pop() ?? path;
  return name.startsWith('.env') || SCANNED_EXTENSIONS.has(extname(name));
}

async function trackedFiles(root: string): Promise<string[]> {
  const { stdout } = await execFileAsync('git', ['ls-files', '-z'], {
    cwd: root,
    maxBuffer: 64 * 1024 * 1024,
  });
  return stdout.split('\0').filter((path) => path.length > 0 && isScanned(path));
}

async function main(): Promise<void> {
  const root = resolve(process.cwd());
  const findings: string[] = [];

  for (const path of await trackedFiles(root)) {
    const lines = (await readFile(resolve(root, path), 'utf8')).split('\n');
    lines.forEach((line, index) => {
      if (PICTOGRAPHIC.test(line)) {
        findings.push(`${relative(root, resolve(root, path))}:${String(index + 1)}`);
      }
    });
  }

  if (findings.length > 0) {
    process.stdout.write(`Emoji found in ${String(findings.length)} location(s):\n${findings.join('\n')}\n`);
    process.exitCode = 1;
    return;
  }
  process.stdout.write('No emoji found.\n');
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : 'unknown error';
  process.stderr.write(`${message}\n`);
  process.exitCode = 1;
});
